/* Three research roles; two executed feedback loops. Recorded evidence only. */
(() => {
  'use strict';
  const old=window.ResearchObservatory, D=window.OBSERVATORY_TEAM, H=window.ResearchHub;
  if (!old || !D || !H) return;
  const esc=H.escape, safe=H.safeURL;
  const rows=v=>Array.isArray(v)&&v.every(x=>x&&typeof x==='object'&&!Array.isArray(x))?v:[];
  const link=(r,t)=>`<a href="#research/${esc(r)}">${esc(t)}</a>`;
  const eq=t=>`<div class="hub-eq" aria-label="Mathematical statement">${esc(t)}</div>`;
  const panel=(t,b)=>`<section class="hub-panel"><h2>${esc(t)}</h2>${b}</section>`;
  const head=(t,b)=>`<header class="hub-header"><p class="hub-kicker">Yang–Mills Workbench · Round 14 · Three roles, two loops</p><h1>${esc(t)}</h1><p class="hub-deck">${esc(b)}</p></header>`;
  const table=(heads,data)=>`<div class="hub-table-wrap"><table class="hub-table"><thead><tr>${heads.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${data.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const documents=D.documents&&typeof D.documents==='object'?D.documents:{};
  const doc=(k,t)=>Object.hasOwn(documents,k)?`<button data-r-doc="round14/${esc(k)}">${esc(t)}</button>`:'';
  const pages={home:'Research home','team-map':'Team & network','team-loop1':'Loop 1: derive & challenge','team-loop2':'Loop 2: exact certificate','team-roadmap':'Forward & backward roadmap','team-review':'Skeptic & reproduction'};
  function graph(){
    const nodes=rows(D.collaboration?.nodes),edges=rows(D.collaboration?.edges);
    if(!nodes.length||!nodes.every(n=>typeof n.id==='string'&&Number.isFinite(n.x)&&Number.isFinite(n.y))) return '<p role="status">The recorded collaboration graph is unavailable.</p>';
    const byId=new Map(nodes.map(n=>[n.id,n]));
    const paths=edges.filter(e=>byId.has(e.from)&&byId.has(e.to)).map(e=>{const a=byId.get(e.from),b=byId.get(e.to);const same=a.y===b.y;return `<path d="M${same?a.x+130:a.x} ${same?a.y:a.y+27} L${same?b.x-130:b.x} ${same?b.y:b.y-29}" stroke="currentColor" stroke-width="1.8" fill="none" opacity=".55" marker-end="url(#team-arrow)" ${same?'marker-start="url(#team-arrow)"':''}/>`;}).join('');
    const boxes=nodes.map(n=>`<a href="#research/${esc(n.route)}" aria-label="${esc(n.label)}: ${esc(n.status)}"><rect x="${n.x-124}" y="${n.y-24}" width="248" height="48" rx="9" fill="var(--panel,#f7f5ee)" stroke="currentColor"/><text x="${n.x}" y="${n.y-3}" text-anchor="middle" font-size="13" fill="currentColor">${esc(n.label)}</text><text x="${n.x}" y="${n.y+14}" text-anchor="middle" font-size="10" fill="currentColor">${esc(n.status)}</text></a>`).join('');
    return `<svg viewBox="0 0 860 565" role="img" aria-label="Recorded collaboration: advisor contract, two forward and backward research loops with exchanged challenges, evidence gates, and next roadmap" style="width:100%;min-width:300px;max-height:565px"><defs><marker id="team-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10z" fill="currentColor"/></marker></defs>${paths}${boxes}</svg>`;
  }
  function plot(key){
    const p=D.plots?.[key];
    if(!p||!Array.isArray(p.series)||!p.series.length||!p.series.every(s=>s&&Array.isArray(s.points)&&s.points.length&&s.points.every(q=>Array.isArray(q)&&q.length===2&&q.every(Number.isFinite))))return '<p class="hub-empty" role="status">No valid recorded data are available for this plot.</p>';
    return old.chart(p.series,{title:p.title,xLabel:p.xLabel,yLabel:p.yLabel,zero:false})+`<p class="hub-plot-caption">${esc(p.caption)}</p><a href="${safe(p.csv)}" download>Download plotted CSV</a>`;
  }
  function home(){return head('Two research loops, with a result the team can replay','The team derived how an explicit mixed-loop coupling creates correlation, challenged the approximation, then used exact arithmetic to certify a finite-model result beyond the first sufficient bound.')+
    panel('What this round establishes',table(['Result','Detailed summary','Evidence'],[
      ['A matched, nonfactorized finite model','For two SU(2) holonomies, the new coefficient η multiplies the actual mixed trace z=Tr(UV)/2. The unchanged η=0 planar Wilson baseline factorizes. At nonzero η the finite action is explicitly deformed; its correlation must be calculated.',link('team-loop1','Measure, equations and exception cases')],
      ['Exact susceptibility and a controlled sign range','At zero deformation, the derivative of Cov(x,y) is the product of the two single-loop variances. The forward/backward debate improved a valid bound on the second derivative from 26 to 7. Existing exact variance evidence then certifies small signed deformations.',link('team-loop1','Derivation and perturbative intervals')],
      ['An exact nonperturbative point enclosure',esc(D.metrics?.central_summary||'Inspect the accepted exact certificate and its degree before interpreting this result.'),link('team-loop2','Rational certificate and independent verification')],
      ['A working two-direction proof planner','The finite rule library is searched from premises and from target obligations. Accepted paths have a recorded meeting and a separately replayed ordered certificate. Removing required evidence blocks the corresponding route.',link('team-roadmap','Executed routes and missing bridges')],
      ['Two completed feedback decisions','The first loop selected a point where the simple bound was inconclusive. The second loop addressed that specific gap with independent group-integral formulas, exact remainders and mutation tests. The next experiment is specified, not presented as already completed.',link('team-map','Team graph and actual feedback')]
    ]))+
    panel('How to explore and reproduce it','<ol><li>Open the team network to see who derived, challenged and accepted each result.</li><li>Read loop one for the model and analytic statements. The ordinary baseline and changed action are both explicit.</li><li>Read loop two for exact rational error bounds. Download the certificates and run the independent verifier locally.</li><li>Use the roadmap to follow both directions: consequences of known premises and requirements of the desired theorem.</li><li>Inspect the skeptic page for failed targets, corrected code, source coverage and local launch commands.</li></ol><p>Plots show saved experiments. They do not execute Python in your browser. Document buttons open escaped source text; the repository retains editable equations and code.</p>')+
    panel('Keep earlier results in their original scope',table(['Preserved work','What it supports','Page'],[
      ['Fixed-spacing Hamiltonian stability','A qualitative volume-uniform gap at sufficiently small magnetic/electric ratio; the numerical threshold remains unevaluated.',link('strong-coupling','Restricted gap theorem')],
      ['One-loop compact hierarchy','Exact moment intervals, all-order uniqueness and a scalar response identity for the specified Euclidean measure.',link('moment-bounds','Earlier exact moment evidence')],
      ['Finite-graph dynamics and locality','Certified driven state error and fixed-spacing boundary estimates, with their separate state and time conventions.',link('dynamic-proof','Dynamic theorem')],
      ['Einstein–QED branch','Finite response/scalar/gravity results remain distinct until a common renormalized current and stress are constructed.',link('variables','Earlier branch')]
    ]))+
    panel('The four-dimensional Yang–Mills problem remains open','<p>A finite static covariance supplies neither a physical generator nor a nontrivial continuum field theory. No mass parameter was fitted to make this result into a gap. The state, action, volume limit, scale matching and reconstruction obligations remain on the backward roadmap.</p><p><a href="https://www.claymath.org/millennium/yang-mills-the-maths-gap/">Official problem and status</a></p>');}
  function team(){return head('Three collaborators, two sequential feedback loops','The advisor also served as skeptic. Two researchers worked in opposite directions and exchanged objections. These are completed agent roles and recorded decisions, not a live swarm or credentialed human review.')+
    panel('Shared collaboration network',graph()+table(['Node','Owner','Recorded status'],rows(D.collaboration?.nodes).map(n=>[link(n.route,n.label),esc(n.owner),esc(n.status)])))+
    panel('Role contracts',table(['Role','Forward or backward work','Acceptance responsibility'],[
      ['Advisor–skeptic','Freeze action, state, observable and parameter definitions; choose a target exposed by the previous failure.','Review mathematical scope, independently check identities, source-bind acceptance and block unsupported bridges.'],
      ['Forward researcher','Derive conditional Haar integrals, test direct quadrature, then produce exact rational moment certificates.','Report actual failures and domains; cannot label producer tests independent.'],
      ['Backward researcher','Start from a certified covariance and the outer spectral target; derive necessary evidence and reconstruct moments via characters.','Recompute arithmetic without the producer oracle; challenge hidden generator and limiting assumptions.']
    ]))+
    panel('Feedback that changed the calculation',table(['Loop / sender','Challenge','Resulting decision'],rows(D.feedback).map(f=>[esc(f.loop+' · '+f.from),esc(f.challenge),esc(f.decision)])))+
    panel('Common variables, different meanings',eq('x=Tr(U)/2, y=Tr(V)/2, z=Tr(UV)/2\nS=k₁x+k₂y+ηz; dμ=Z⁻¹ exp(S)dU dV\nM=|k₁|+|k₂|+|η|; N = polynomial truncation degree')+'<p>The trace z records relative group orientation already present in U and V. The coefficient η changes the finite action. M bounds that action, and N controls a numerical approximation. None of these quantities is a physical mass, continuum lattice spacing or a new dynamical field. A proposed common symbol connects two arguments only after its state and normalization also match.</p>'+doc('protocol','Read the full two-loop protocol'));}
  function loop1(){return head('Loop one: derive the mechanism and challenge its range','Start from a compact, normalized probability measure. Keep every fluctuation needed for covariance and test the exact limits before attempting a certificate.')+
    panel('Action, geometry and baseline',eq('dμ=Z⁻¹e^(k₁x+k₂y+ηz)dU dV\n(z−xy)²≤(1−x²)(1−y²), |x|,|y|≤1\nη=0 ⇒ Z=Z₀(k₁)Z₀(k₂), Cov(x,y)=0')+'<p>U and V are two loop holonomies in a finite Euclidean integral after open planar tree reduction. The η term is an additional bounded mixed-loop interaction. It is not inferred from shared-link Hamiltonian kinetic energy. The undeformed adjacent-square Wilson integral factorizes exactly; omitting that baseline would give a false claim of interaction.</p>')+
    panel('Exact conditional reduction',eq('h²=k₂²+η²+2k₂ηx=(k₂+ηx)²+η²(1−x²)\nZ₀(h)=2I₁(h)/h, Z₀(0)=1\nZ=∫₋₁¹(2/π)√(1−x²)e^(k₁x)Z₀(h)dx\nA=k₂+ηx, B=k₂x+η\nt=I₂(h)/(hI₁(h)), r=I₃(h)/(h²I₁(h))\nE[y|x]=tA, E[z|x]=tB\nE[y²|x]=t+rA², E[z²|x]=t+rB²\nE[yz|x]=tx+rAB; t(0)=1/4, r(0)=1/24')+'<p>The second coefficient can also be written (1−4t)/h², but that subtraction loses precision near zero. The implementation uses a positive Bessel ratio and a small-field series. A zero effective field can occur when nonzero inputs cancel at a central group element; it is a removable limit. The independent three-dimensional angular integral does not call this conditional formula.</p>'+doc('forward1','Read the derivation and numerical contract'))+
    panel('The response is derived rather than fitted',eq('C(η)=Covη(x,y), vᵢ=Var_(kᵢ)(x)\nC(0)=0, C′(0)=v₁v₂>0\nC″=E[δx δy δz²]−Cov(x,y)Var(z)−2Cov(x,z)Cov(y,z)\n|C″|≤4+1+2=7\n|C(η)−ηv₁v₂|≤(7/2)η²')+'<p>Here δ denotes centering in the same deformed measure. Compact support and Cauchy–Schwarz control the terms. The exact derivative is a response to η, not evolution in time. The bound holds for finite real couplings, but its sign conclusion is only sufficient in the interval 0&lt;|η|&lt;2v₁v₂/7.</p>'+table(['Fixture','Certified covariance enclosure','Interpretation'],rows(D.perturbative).map(r=>[esc('k₁=k₂=1, η='+r.eta),esc(r.display),esc(r.status)]))+'<p>The wider η=1/4 enclosure contains zero. That is a failed sign target for this estimate, not evidence that the covariance vanishes. This precise gap selected loop two.</p>'+doc('advisor','Inspect the formal derivative and exact variance transfer'))+
    panel('A useful solvable exception',eq('k₁=k₂=0: W=UV\nU remains Haar and independent of W; W has weight e^(η Tr(W)/2)\nE[x]=E[y]=0, Var(x)=Var(y)=1/4\nC(η)=u(η)/4, u(η)=I₂(η)/I₁(η), u(0)=0')+'<p>The change of group variables proves this slice exactly. It gives a nonfactorized test case whose one-loop response was already certified in the earlier round. It does not solve the general mixed-coupling integral or establish a physical spectral gap.</p>')+
    panel('Recorded comparisons and retained failures',plot('covariance')+plot('quadrature')+`<p>${esc(D.metrics?.loop1_summary||'Recorded validation is available in the source documents.')}</p><p>Coarse quadrature can fail even when the integrand is regular. The original derived-field domain mismatch is preserved: legal input coefficients could produce a conditional field larger than the single-coefficient limit. The corrected helper and its regression are included.</p>`+doc('forwardchecks','Read producer check records')+doc('backward1','Read the independent Haar derivation'));}
  function loop2(){return head('Loop two: an exact enclosure beyond the first sign bound','The same declared finite measure is evaluated by exact polynomial moments with a rigorous exponential remainder. A separate implementation reconstructs the certificate through SU(2) characters.')+
    panel('The accepted target',eq(D.metrics?.central_equation||'The final exact enclosure must be loaded before a result is claimed.')+`<p>${esc(D.metrics?.central_summary||'No accepted interval is loaded.')}</p>`+'<p>Displayed decimal bounds are rounded outward from the rational certificate. The exact endpoints and source hashes are downloadable. This is a finite Euclidean covariance result. It proves neither an infinite-volume correlation rate nor a Hamiltonian mass gap.</p><a href="/research-round14-certificates.json" download>Download exact rational certificates</a>')+
    panel('Entire error budget, including normalization',eq('M=|k₁|+|k₂|+|η|, N+2>M\nR_N=[M^(N+1)/(N+1)!]/[1−M/(N+2)]\nT_N(O)=Σ_(a+b+c≤N) k₁ᵃk₂ᵇηᶜ/(a!b!c!) · E₀[O xᵃyᵇzᶜ]\n|E₀[Oe^S]−T_N(O)|≤R_N for |O|≤1\nZ≥exp(E₀S)=1\nC=(Z A_xy−A_x A_y)/Z²')+'<p>The tail follows by bounding successive absolute Taylor terms with a geometric ratio smaller than one. No floating exponential is used for the proof remainder. Signs remain in the polynomial coefficients. Jensen applies because the undeformed Haar means of x, y and z vanish. The partition interval is intersected with [1,∞), then every signed product and quotient corner is retained. Setting the partition to a point would discard part of the error.</p>')+
    panel('Two independent exact Haar formulas',eq('Quaternion oracle:\nE₀[xᵃyᵇzᶜ]=Σⱼ binom(c,2j)/(2j+1)\n × E[x^(a+c−2j)(1−x²)ʲ] E[y^(b+c−2j)(1−y²)ʲ]\nE[x²ⁿ]=Catalan(n)/4ⁿ; odd moments vanish\nCharacter oracle:\nxᵃ=Σᵣ A_ar χ_r(U)\nE₀[xᵃyᵇzᶜ]=Σᵣ A_ar A_br A_cr/(r+1)')+'<p>The forward oracle integrates the relative quaternion angle. The backward oracle decomposes tensor powers and uses Schur convolution. The representation dimension r+1 is essential. Both formulas share the specified Haar theory; their implementations are independent. Agreement does not certify a changed group, state or action.</p>'+doc('forward2','Read the exact producer method')+doc('backward2','Read independent reconstruction and objections'))+
    panel('Degree refinement and edge cases',plot('certificate')+table(['Fixture','Degree','Accepted conclusion'],rows(D.certificates).map(c=>[esc(c.label),esc(c.degree),esc(c.summary)]))+'<p>The insufficient low-degree target is retained. Zero action has a zero remainder and exact normalization; signed coefficients require signed interval arithmetic. Boolean degrees, malformed fractions, a nonpositive tail denominator and certificate mutations must be rejected. A floating comparator can fall outside an interval much narrower than machine precision without invalidating the exact certificate.</p>')+
    panel('A controlled finite removal of the added variable',eq('Fixed real observable |O|≤1 in the same finite family:\n∂η Eη[O]=Covη(O,z), |∂η Eη[O]|≤1\n|Eη[O]−E₀[O]|≤|η|')+'<p>This bound controls removal of the mixed-loop deformation for each bounded observable. It returns to the exactly factorized finite baseline. It does not establish a volume-uniform many-loop estimate or a continuum equivalence theorem.</p>')+
    panel('When more degree is guaranteed to help','<p>At a fixed finite rational coupling triple, the uncapped Taylor remainder tends to zero. The positive partition bound then makes every displayed interval converge to its true value. If the exact covariance is nonzero, sufficiently large degree eventually certifies its sign. Exact zero need not terminate, and the implementation cap of48 does not promise success for every target. This is a conventional convergence statement, not an executed infinite computation.</p>')+
    panel('Second feedback decision',doc('gate2','Read the final advisor gate')+doc('verification','Read independent verification results')+'<p>The next loop must change the target explicitly. Better finite integration alone cannot fill the missing state/generator or continuum premises. The proposed follow-up combines a broader same-action certificate with a separately tracked spectral bridge.</p>'+link('team-roadmap','Open the next bounded experiments'));}
  function roadmap(){return head('Attack the same target from both directions','Forward steps derive consequences from available premises. Backward steps expose sufficient missing premises. The meeting is accepted only for the same action, state, observable and scale.')+
    panel('Executed search, not just a diagram',table(['Route / withdrawal test','Recorded result','Rule cost'],rows(D.routes).map(r=>[esc(r.name),esc(r.status),esc(r.cost??'No completed route')])))+
    panel('What the search checks','<p>The reviewed historical planner explores a finite library of positive ground rules in both directions. It records a meeting, then replays the ordered rule certificate separately. Source fingerprints bind the replay to the frozen scientific files. This is a dependency planner with reviewed mathematical implications, not a proof assistant deriving analysis from axioms. Its optimality is only within the supplied rule library.</p>'+doc('proof','Inspect actual meetings and ordered proofs'))+
    panel('Detailed next roadmap',table(['Priority / ownership','Forward attack','Backward obligation','Failure test and stopping gate'],rows(D.roadmap).map(r=>[esc(r.id+' · '+r.owner+' · '+r.status),esc(r.forward),esc(r.backward),esc(r.gate)])))+
    panel('Outer spectral requirement',eq('H≥0, HΩ=0; ψ in a dense subset of Ω⊥\nFor a common Δ>0, all t≥0:\n⟨ψ,e^(−tH)ψ⟩≤Cψ e^(−Δt)\n⇒ no spectral weight in (0,Δ) on Ω⊥')+'<p>This sufficient criterion starts after a physical Hilbert space and generator have been constructed and matched. Each Cψ may depend on ψ but must be finite; Δ is common. Finite static covariance gives none of the required large-time inequalities. The continuum target additionally needs its nontrivial field theory and limiting axioms.</p>')+
    panel('Why a convenient extra constant is insufficient',eq('Same static space L²(μ), vacuum Ω=1\nChoose a complete orthonormal basis eₙ of Ω⊥\nH eₙ=(1/n)eₙ; HΩ=0\nH≥0, unique vacuum, inf positive energies=0')+'<p>This countermodel preserves the static moments while leaving arbitrarily small excitations. It is not asserted to be the Yang–Mills generator. It demonstrates why a generator-matching premise cannot be inferred from the finite moments. Adding a chosen positive mass to this operator would change the target.</p>'+doc('roadmap','Read the expanded stepwise roadmap and next-loop contract'));}
  function review(){return head('Skeptic review, retained failures and reproduction','Acceptance is attached to specific source bytes and evidence classes. Producer tests, independent reconstruction and conventional proofs are reported separately.')+
    panel('Actual review ledger',table(['Review','Recorded status','What it checks'],rows(D.reviews).map(r=>[esc(r.name),esc(r.status),esc(r.scope)])))+
    panel('Failures that changed this round',table(['Finding','Repair or decision','Scope retained'],rows(D.failures).map(r=>[esc(r.finding),esc(r.action),esc(r.limit)])))+
    panel('Local launch and research commands','<p>Clone the repository and run <code>python3 start.py</code>, then open <code>http://127.0.0.1:8001/#research</code>. The website needs no API key. Install the scientific requirements to rerun numerical comparisons; the rational certificate tools use the Python standard library.</p><p><a href="https://github.com/occult-kranti/yang_mills_workbench#readme">Detailed README and local setup</a></p>'+doc('readme','Open this round’s exact reproduction commands')+'<p>The archive contains source, exact rational outputs, CSV histories, review records and proof routes. Normal and optimized Python reruns test that validation does not depend on removable assert statements; they are not counted as separate independent scientific reviews.</p>')+
    panel('Primary-source coverage',table(['Source','Reading depth','Limit'],rows(D.sources).map(s=>[`<a href="${safe(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`,esc(s.reading_depth||s.reading_scope||''),esc(s.limitations||s.limitation||'')]))+doc('sources','Read the source-specific theorem and constant audit'))+
    panel('What remains unverified','<p>The source audit did not extract a numerical smallness threshold from the Hamiltonian stability theorem. A Langevin mixing constant is not a matched physical Hamiltonian gap. The finite η-deformed measure has no demonstrated continuum Yang–Mills equivalence. No claim is made to exhaust all research literature or all solution strategies.</p><p>Interface routes, document handlers, recorded-data bindings and local/static hosting are tested in code. Real-browser visual layout and keyboard interaction have not been audited in this run.</p>');}
  const functions={home,'team-map':team,'team-loop1':loop1,'team-loop2':loop2,'team-roadmap':roadmap,'team-review':review};
  const registry=window.OBSERVATORY_RESEARCH?.documents;
  if(registry&&typeof registry==='object')for(const [k,v] of Object.entries(documents))if(/^[a-z][a-z0-9_-]*$/.test(k))registry['round14/'+k]=v;
  function render(route='home'){
    if(route==='review13-home')return `<p class="hub-limit">Historical round 13 snapshot. ${link('home','Current two-loop results')}</p>`+old.render('home');
    if(!Object.hasOwn(functions,route))return old.render(route);
    return `<div class="research-shell hub m8"><nav class="hub-nav" aria-label="Current research navigation">${Object.entries(pages).map(([r,t])=>`<a href="#research/${r}" ${r===route?'aria-current="page"':''}>${esc(t)}</a>`).join('')}</nav>${functions[route]()}<footer class="hub-foot"><a href="/research-round14.zip" download>Download both research loops</a> · <a href="/research-round14-certificates.json" download>Exact certificates</a> · ${link('review13-home','Previous research snapshot')} · <a href="https://github.com/occult-kranti/yang_mills_workbench#readme">Repository and local launch</a></footer></div>`;
  }
  window.ResearchTeam={render,graph,plot};
  window.ResearchObservatory={...old,render,afterRender(){const r=location.hash.split('/')[1]||'home';if(Object.hasOwn(pages,r))document.title=pages[r]+' · Yang–Mills Workbench';else old.afterRender();}};
})();
